//! Every state an EC2 instance moves into reaches EventBridge as an
//! `EC2 Instance State-change Notification` from `aws.ec2`, the event Cluster API Provider AWS
//! reads instance state from. Sources: the EC2 User Guide, "Amazon EventBridge events for
//! Amazon EC2 instance state changes", for the source, detail type, `detail` members and
//! `resources`; "events generated by AWS services go to your account's default event bus".
//!
//! Each case reads the events off an SQS queue a rule on that pattern targets, and makes no
//! EC2 call while it waits, so a state the clock moves the instance into has to be published
//! without anybody asking EC2 for it.

use aws_emulator_fork_router::{build_services, InMemoryEngine};
use bytes::Bytes;
use serde_json::{json, Value};
use smithy_server_runtime::MultiServiceRouter;
use std::sync::Arc;
use std::time::{Duration, Instant};

const REGION: &str = "us-west-2";

/// Spelled out rather than imported, so a wrong constant in the EC2 crate cannot pass.
const EC2_SOURCE: &str = "aws.ec2";
const STATE_CHANGE: &str = "EC2 Instance State-change Notification";

/// The AMI the EC2 crate's own launch tests use.
const AMI: &str = "ami-0123456789abcdef0";

/// How long a case waits for the events it expects. Each state is owed 500 ms after the one
/// before it, so this leaves room for a slow CI runner.
const DEADLINE: Duration = Duration::from_secs(20);
const POLL_INTERVAL: Duration = Duration::from_millis(100);

/// Assembling the router needs a larger stack than a test thread has (see main.rs).
const ROUTER_STACK_SIZE: usize = 64 * 1024 * 1024;

fn on_router_thread(case: impl FnOnce(MultiServiceRouter) -> std::pin::Pin<Box<dyn std::future::Future<Output = ()>>> + Send + 'static) {
    std::thread::Builder::new()
        .stack_size(ROUTER_STACK_SIZE)
        .spawn(move || {
            let runtime = tokio::runtime::Builder::new_multi_thread()
                .worker_threads(2)
                .thread_stack_size(ROUTER_STACK_SIZE)
                .enable_all()
                .build()
                .expect("a tokio runtime");
            let mut router = build_services(Arc::new(InMemoryEngine::new()));
            router.set_request_authentication(false);
            runtime.block_on(case(router));
        })
        .expect("spawn the router thread")
        .join()
        .expect("the case passes");
}

fn authorization(service: &str) -> String {
    format!(
        "AWS4-HMAC-SHA256 Credential=AKIDEXAMPLE/20260101/{REGION}/{service}/aws4_request, \
         SignedHeaders=host, Signature=0000"
    )
}

/// One `X-Amz-Target` JSON call that must answer 200.
async fn rpc(router: &MultiServiceRouter, signing_name: &str, target: &str, version: &str, body: &Value) -> Value {
    let request = http::Request::builder()
        .method("POST")
        .uri("/")
        .header("host", format!("{signing_name}.{REGION}.amazonaws.com"))
        .header("authorization", authorization(signing_name))
        .header("content-type", format!("application/x-amz-json-{version}"))
        .header("x-amz-target", target)
        .body(Bytes::from(body.to_string()))
        .expect("a well-formed request");
    let response = router.dispatch(request).await;
    let status = response.status().as_u16();
    let parsed: Value = serde_json::from_slice(response.body()).unwrap_or(Value::Null);
    assert_eq!(status, 200, "{target} answered {status}: {parsed}");
    parsed
}

async fn events(router: &MultiServiceRouter, operation: &str, body: &Value) -> Value {
    rpc(router, "events", &format!("AWSEvents.{operation}"), "1.1", body).await
}

async fn sqs(router: &MultiServiceRouter, operation: &str, body: &Value) -> Value {
    rpc(router, "sqs", &format!("AmazonSQS.{operation}"), "1.0", body).await
}

/// One EC2 query call that must answer 200; answers the XML body.
async fn ec2(router: &MultiServiceRouter, action: &str, params: &[(&str, &str)]) -> String {
    let mut body = format!("Action={action}&Version=2016-11-15");
    for (name, value) in params {
        body.push_str(&format!("&{name}={value}"));
    }
    let request = http::Request::builder()
        .method("POST")
        .uri(format!("https://ec2.{REGION}.amazonaws.com/"))
        .header("content-type", "application/x-www-form-urlencoded")
        .header("authorization", authorization("ec2"))
        .body(Bytes::from(body))
        .expect("a well-formed request");
    let response = router.dispatch(request).await;
    let text = String::from_utf8_lossy(response.body()).to_string();
    assert_eq!(response.status().as_u16(), 200, "{action} answered {}: {text}", response.status());
    text
}

/// The text of the first `<name>` element.
fn element(xml: &str, name: &str) -> String {
    let open = format!("<{name}>");
    let start = xml.find(&open).unwrap_or_else(|| panic!("no <{name}> in {xml}")) + open.len();
    let end = xml[start..].find('<').expect("a closing tag") + start;
    xml[start..end].to_string()
}

/// A queue whose policy admits EventBridge, targeted by a rule on EC2's state changes.
async fn watched_queue(router: &MultiServiceRouter) -> String {
    let url = sqs(router, "CreateQueue", &json!({"QueueName": "instance-state"})).await["QueueUrl"]
        .as_str()
        .expect("a queue url")
        .to_string();
    let attributes = sqs(router, "GetQueueAttributes", &json!({"QueueUrl": &url, "AttributeNames": ["QueueArn"]})).await;
    let arn = attributes["Attributes"]["QueueArn"].as_str().expect("a queue arn").to_string();
    let policy = json!({
        "Version": "2012-10-17",
        "Statement": [{"Effect": "Allow", "Principal": {"Service": "events.amazonaws.com"}, "Action": "sqs:SendMessage", "Resource": &arn}],
    });
    sqs(router, "SetQueueAttributes", &json!({"QueueUrl": &url, "Attributes": {"Policy": policy.to_string()}})).await;
    let pattern = json!({"source": [EC2_SOURCE], "detail-type": [STATE_CHANGE]});
    events(router, "PutRule", &json!({"Name": "instance-state", "EventPattern": pattern.to_string(), "State": "ENABLED"})).await;
    let targeted = events(router, "PutTargets", &json!({"Rule": "instance-state", "Targets": [{"Id": "queue", "Arn": &arn}]})).await;
    assert_eq!(targeted["FailedEntryCount"], json!(0), "{targeted}");
    url
}

/// Read events off the queue until `wanted` states of `instance_id` have arrived or the
/// deadline passes; answers the envelopes about that instance, in arrival order.
async fn states_of(router: &MultiServiceRouter, url: &str, instance_id: &str, wanted: usize) -> Vec<Value> {
    let started = Instant::now();
    let mut arrived = Vec::new();
    while arrived.len() < wanted && started.elapsed() < DEADLINE {
        let received = sqs(router, "ReceiveMessage", &json!({"QueueUrl": url, "MaxNumberOfMessages": 10})).await;
        for message in received["Messages"].as_array().cloned().unwrap_or_default() {
            sqs(router, "DeleteMessage", &json!({"QueueUrl": url, "ReceiptHandle": message["ReceiptHandle"]})).await;
            let envelope: Value = serde_json::from_str(message["Body"].as_str().unwrap_or_default()).unwrap_or(Value::Null);
            if envelope["detail"]["instance-id"] == json!(instance_id) {
                arrived.push(envelope);
            }
        }
        if arrived.len() < wanted {
            tokio::time::sleep(POLL_INTERVAL).await;
        }
    }
    arrived
}

fn state_names(envelopes: &[Value]) -> Vec<String> {
    envelopes
        .iter()
        .map(|envelope| envelope["detail"]["state"].as_str().unwrap_or("<none>").to_string())
        .collect()
}

#[test]
fn a_launched_then_terminated_instance_announces_each_state_it_moves_into() {
    on_router_thread(|router| {
        Box::pin(async move {
            let url = watched_queue(&router).await;

            let launched = ec2(&router, "RunInstances", &[("ImageId", AMI), ("MinCount", "1"), ("MaxCount", "1")]).await;
            let instance_id = element(&launched, "instanceId");
            let first = states_of(&router, &url, &instance_id, 2).await;
            ec2(&router, "TerminateInstances", &[("InstanceId.1", &instance_id)]).await;
            let second = states_of(&router, &url, &instance_id, 2).await;

            let envelopes: Vec<Value> = first.into_iter().chain(second).collect();
            assert_eq!(state_names(&envelopes), ["pending", "running", "shutting-down", "terminated"]);
            for envelope in &envelopes {
                assert_eq!(envelope["source"], json!(EC2_SOURCE), "{envelope}");
                assert_eq!(envelope["detail-type"], json!(STATE_CHANGE), "{envelope}");
                assert_eq!(envelope["region"], json!(REGION), "{envelope}");
                let resource = envelope["resources"][0].as_str().unwrap_or_default();
                assert!(
                    resource.starts_with(&format!("arn:aws:ec2:{REGION}:")) && resource.ends_with(&format!(":instance/{instance_id}")),
                    "resources[0] is {resource}"
                );
            }
        })
    });
}

#[test]
fn a_stopped_then_started_instance_announces_each_state_it_moves_into() {
    on_router_thread(|router| {
        Box::pin(async move {
            let url = watched_queue(&router).await;
            let launched = ec2(&router, "RunInstances", &[("ImageId", AMI), ("MinCount", "1"), ("MaxCount", "1")]).await;
            let instance_id = element(&launched, "instanceId");
            let launch = states_of(&router, &url, &instance_id, 2).await;
            assert_eq!(state_names(&launch), ["pending", "running"]);

            ec2(&router, "StopInstances", &[("InstanceId.1", &instance_id)]).await;
            let stop = states_of(&router, &url, &instance_id, 2).await;
            ec2(&router, "StartInstances", &[("InstanceId.1", &instance_id)]).await;
            let start = states_of(&router, &url, &instance_id, 2).await;

            assert_eq!(state_names(&stop), ["stopping", "stopped"]);
            assert_eq!(state_names(&start), ["pending", "running"]);
        })
    });
}
